SELECT p.id AS product_id, p.name,p.grade,p.charge_name AS productChargeName,pi.project_status, pi.charge_name AS projectChargeName,p.create_time productCreateTime,pa.archive_time FROM product_info p LEFT JOIN project_info pi ON p.id=pi.product_id INNER JOIN product_archive pa ON pa.product_id=p.id
P.category_id=#{params.categoryId}
AND p.name LIKE concat('%',#{params.searchKeyword},'%')
